/**
 * Every HTML document the app loads — the Electron pages in src/html, the Capacitor, headless and web shells
 * generated by scripts/build-react.ts — carries its own Content-Security-Policy, and none runs an inline script
 * that policy would not allow (script-src 'self' only, so any inline script is a violation).
 */

import path from 'node:path';
import type * as capacitor_config_jsonModule from '../../capacitor.config.json';
import {
    HEADLESS_FLAG_FILE,
    HEADLESS_FLAG_SOURCE,
    NOTICES_ASSET_NAME,
    PHOTO_HOST,
    androidCsp,
    baseCsp,
    capacitorIndexHtml,
    headlessHtml,
    webHtml,
} from '../../scripts/build-react';
import { NOTICES_ASSET_NAME as LOADER_NOTICES_ASSET_NAME } from '../../src/ts/thirdPartyNotices';
import { buildPhotoUrl } from '../../src/ts/format/photoUrl';

// tests/setup.ts mocks fs globally; the documents are read from disk for real.
const fs = jest.requireActual<typeof import('node:fs')>('node:fs');

const HTML_DIR = path.join(__dirname, '..', '..', 'src', 'html');
const electronPages = fs.readdirSync(HTML_DIR).filter((name) => name.endsWith('.html'));

const documents: Array<{ name: string; html: string; kind: 'desktop' | 'android' }> = [
    ...electronPages.map((name) => ({
        name: `src/html/${name}`,
        html: fs.readFileSync(path.join(HTML_DIR, name), 'utf8'),
        kind: 'desktop' as const,
    })),
    { name: 'dist/index.html', html: capacitorIndexHtml, kind: 'android' },
    { name: 'dist/headless.html', html: headlessHtml, kind: 'android' },
    { name: 'dist/web.html', html: webHtml, kind: 'desktop' },
];

const cspOf = (html: string): Map<string, string[]> => {
    const meta = html.match(/<meta\s+http-equiv="Content-Security-Policy"\s+content="([^"]*)"/);
    if (!meta) return new Map();
    return new Map(
        meta[1]
            .split(';')
            .map((part) => part.trim().split(/\s+/))
            .filter((tokens) => tokens[0])
            .map(([name, ...sources]): [string, string[]] => [name, sources]),
    );
};

const inlineScripts = (html: string) =>
    [...html.matchAll(/<script\b([^>]*)>([\s\S]*?)<\/script\b[^>]*>/gi)].filter(([, attrs]) => !/\bsrc=/i.test(attrs));

describe('generated HTML documents', () => {
    test('the Electron pages are the ones this test expects', () => {
        expect([...electronPages].sort()).toEqual(['app.html', 'login.html', 'logs.html']);
    });

    describe.each(documents)('$name', ({ html, kind }) => {
        const csp = cspOf(html);

        test('carries a Content-Security-Policy that locks the document down', () => {
            expect(csp.size).toBeGreaterThan(0);
            expect(csp.get('default-src')).toEqual(["'self'"]);
            expect(csp.get('object-src')).toEqual(["'none'"]);
            expect(csp.get('form-action')).toEqual(["'none'"]);
            expect(csp.get('base-uri')).toEqual(["'self'"]);
            expect(csp.get('script-src')).not.toContain("'unsafe-inline'");
            expect(csp.get('script-src')).not.toContain("'unsafe-eval'");
        });

        test('only draws images from itself, data: and the photo CDN', () => {
            expect(csp.get('img-src')).toEqual(["'self'", 'data:', PHOTO_HOST]);
        });

        test('has no inline script, inline handler or javascript: URL the policy would block', () => {
            expect(inlineScripts(html)).toEqual([]);
            expect(html).not.toMatch(/\son[a-z]+\s*=/i);
            expect(html).not.toMatch(/javascript:/i);
        });

        test('allows WebAssembly compilation only on the Android documents', () => {
            if (kind === 'android') expect(csp.get('script-src')).toContain("'wasm-unsafe-eval'");
            else expect(csp.get('script-src')).toEqual(["'self'"]);
        });

        test('keeps connect-src to the hosts the document talks to', () => {
            expect(csp.get('connect-src')).toEqual(
                kind === 'android' ? ["'self'", 'https://api.github.com', PHOTO_HOST] : ["'self'"],
            );
        });
    });

    test('the Electron pages and the web shell share the base policy', () => {
        const base = baseCsp();
        for (const { html, kind } of documents) {
            if (kind === 'desktop') expect(html).toContain(`content="${base}"`);
        }
    });

    test('the Android documents share the Android policy', () => {
        expect(capacitorIndexHtml).toContain(`content="${androidCsp}"`);
        expect(headlessHtml).toContain(`content="${androidCsp}"`);
    });

    test('pinch-zoom works on Android: the viewport allows it and the WebView is made zoomable', () => {
        const viewport = capacitorIndexHtml.match(/<meta name="viewport" content="([^"]*)"/)?.[1];
        expect(viewport).toBe('width=device-width, initial-scale=1.0, viewport-fit=cover');
        expect(viewport).not.toContain('user-scalable');
        const { android } = require('../../capacitor.config.json') as typeof capacitor_config_jsonModule;
        expect(android.zoomEnabled).toBe(true);
    });

    test('the headless flag is an external script that runs before the deferred bundle', () => {
        expect(headlessHtml.indexOf(`src="${HEADLESS_FLAG_FILE}"`)).toBeGreaterThan(-1);
        expect(headlessHtml.indexOf(HEADLESS_FLAG_FILE)).toBeLessThan(headlessHtml.indexOf('headless-bundle.js'));
        expect(HEADLESS_FLAG_SOURCE).toBe('window.__GS_HEADLESS__ = true;\n');
    });

    test('the photo CDN allowed by img-src is the one buildPhotoUrl emits', () => {
        const id = 'a'.repeat(32);
        expect(buildPhotoUrl(id, id)?.startsWith(`${PHOTO_HOST}/`)).toBe(true);
    });

    test('the notices file copied into dist/ is the one the Android loader fetches', () => {
        expect(NOTICES_ASSET_NAME).toBe(LOADER_NOTICES_ASSET_NAME);
    });
});
